/* Evidence-first case workpaper. All packet strings are escaped before rendering. */
const API='/api', $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=v=>typeof v==='number'?(v<0?'−':'')+'$'+Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:2}):esc(v), fmtDate=v=>v?new Date(v).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}):'—', jparse=x=>{try{return JSON.parse(x)}catch{return x}}, roleEl=$('#role');
let role=roleEl.value, packet=null,state=null,issues=[],validation=null,page='overview',versionIndex=2,filter='',docFilter='all',issueFilter='all',selectedLine=null,selectedDoc=null,selectedIssue=null,returnFilter='all',valuePage=0,noticeDraft='',selectedIssues=new Set();
const roles={Preparer:'st-01',Reviewer:'st-02',Partner:'st-03',Client:null,'Firm administrator':'st-05',Examiner:null}, roleUser=()=>roles[role]||role;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function get(path){const r=await fetch(API+path,{headers:{'X-Demo-Role':role}});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
async function post(path,body){const r=await fetch(API+path,{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Role':role},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');if(d.state)state=d.state;return d}
async function reload(){try{[packet,state,issues,validation]=await Promise.all([get('/packet'),get('/state'),get('/issues'),get('/validation')]);if(role==='Client'||role==='Examiner')page='overview';render()}catch(e){$('#main').innerHTML=`<section class="card"><h2>Start the local case server</h2><p class="sub">The app uses a local SQLite API so review notes and decisions persist across refreshes.</p><div class="sourcepaper">In PowerShell:\ncd "${esc(location.pathname.replace(/\/workpaper\.html$/,''))}"\npython server.py</div><p class="sub">Then open http://127.0.0.1:8765/workpaper.html</p><p class="sub">${esc(e.message)}</p></section>`}}
function updateRoleNav(){const show=role==='Client'?new Set(['overview','requests','filing']):role==='Examiner'?new Set(['overview','filing']):null;document.querySelectorAll('.nav [data-page]').forEach(b=>b.classList.toggle('hide',!!show&&!show.has(b.dataset.page)));document.querySelectorAll('#mobileNav option').forEach(o=>o.hidden=!!show&&!show.has(o.value));$('#mobileNav').value=page;$('.avatar').textContent=role==='Client'?'CL':role==='Reviewer'?'RV':role==='Partner'?'PT':role==='Firm administrator'?'AD':role==='Examiner'?'EX':'PR';}
roleEl.addEventListener('change',async()=>{role=roleEl.value;updateRoleNav();selectedDoc=null;selectedLine=null;selectedIssue=null;await reload()});updateRoleNav();
$('#mobileNav').addEventListener('change',()=>go($('#mobileNav').value));
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b)return;page=b.dataset.page;document.querySelectorAll('.nav [data-page]').forEach(x=>x.classList.toggle('selected',x===b));render()});
$('#searchToggle').addEventListener('click',()=>openSearch());window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
function issueStatus(i){return state?.decisions?.[i.id]||i.status}function openIssues(){return issues.filter(i=>!['resolved','deferred'].includes(issueStatus(i)))}function v(){return packet?.return_versions?.[versionIndex]||packet?.return_versions?.at(-1)}function current(){return packet?.return_versions?.at(-1)}function totalLines(){return (current()?.lines||[]).length}function fmtNum(v){return Number(v||0).toLocaleString('en-US')}
function pageHead(title,sub,actions=''){return `<div class="headrow"><div><div class="eyebrow">2025 TAX YEAR · ${esc(role.toUpperCase())} VIEW</div><h1>${esc(title)}</h1><div class="sub">${sub}</div></div><div class="headactions">${actions}</div></div>`}
function issueBadge(){const n=openIssues().length;$('#issueBadge').textContent=n;$('#issueBadge').classList.toggle('hide',!n)}
function stats(){let s=(role==='Client'||role==='Examiner')?packet.summary:current().summary;let federal=s?.federal||{},ca=s?.california||{};let blocked=state.review_notes.filter(n=>n.blocking&&n.status==='open').length;return `<div class="gridstats"><button class="stat" data-go="return"><label>Federal balance due · supplied v3</label><strong>${money(federal.balance_due)}</strong><small>Total tax ${money(federal.total_tax)} · AGI ${money(federal.agi)}</small></button><button class="stat" data-go="return"><label>California overpayment · supplied v3</label><strong class="green">${money(Math.abs(ca.balance_due||0))}</strong><small>Total tax ${money(ca.total_tax)} · CA AGI ${money(ca.ca_agi)}</small></button><button class="stat" data-go="issues"><label>Open issue records</label><strong class="${openIssues().length?'orange':''}">${fmtNum(openIssues().length)}</strong><small>${issues.length-openIssues().length} resolved or deferred</small></button><button class="stat" data-go="review"><label>Blocking review notes</label><strong class="${blocked?'red':''}">${blocked}</strong><small>${state.signoffs.filter(s=>s.status==='approved').length} sign-offs · persisted in SQLite</small></button></div>`}
function refs(rs=[]){return `<span class="refs">${rs.map(r=>`<button class="ref" data-ref="${esc(r)}">${esc(r)}</button>`).join('')}</span>`}
function issueCard(i,selectable=false){const status=issueStatus(i),done=status==='resolved';return `<article class="issue">${selectable?`<input type="checkbox" class="issue-select" data-select-issue="${esc(i.id)}" ${selectedIssues.has(i.id)?'checked':''} aria-label="Select ${esc(i.title)}">`:''}<div><h3>${esc(i.title)} <span class="risk ${esc(i.severity)}">${esc(i.severity.toUpperCase())}</span> ${done?'<span class="risk done">RESOLVED</span>':''}</h3><p>${esc(i.description)}</p><div class="refs">Evidence ${refs(i.refs)}</div>${state.decision_notes?.[i.id]?`<div class="softnote">Resolution: ${esc(state.decision_notes[i.id])}</div>`:''}</div><div class="issue-actions"><select class="select issue-status" data-issue="${esc(i.id)}"><option value="open" ${status==='open'?'selected':''}>Open</option><option value="in_review" ${status==='in_review'?'selected':''}>In review</option><option value="resolved" ${done?'selected':''}>Resolved</option><option value="deferred" ${status==='deferred'?'selected':''}>Deferred</option></select><button class="btn small" data-issue-detail="${esc(i.id)}">Inspect</button></div></article>`}
function render(){if(!packet||!state)return;issueBadge();const actorReadOnly=['Client','Examiner'].includes(role);if(role==='Client'){renderClient();return}if(role==='Examiner'){renderExaminer();return}const main=$('#main');if(page==='overview')main.innerHTML=renderOverview();else if(page==='return')main.innerHTML=renderReturn();else if(page==='evidence')main.innerHTML=renderEvidence();else if(page==='calculations')main.innerHTML=renderCalculations();else if(page==='issues')main.innerHTML=renderIssues();else if(page==='review')main.innerHTML=renderReview();else if(page==='changes')main.innerHTML=renderChanges();else if(page==='requests')main.innerHTML=renderRequests();else if(page==='filing')main.innerHTML=renderFiling();else if(page==='carryovers')main.innerHTML=renderCarryovers();else if(page==='operations')main.innerHTML=renderOperations();else if(page==='settings')main.innerHTML=renderSettings();else main.innerHTML=renderOverview();bind();}
function renderOverview(){const v3=current(),f=packet.firm,assigned=Object.values(f.assignment_at_start||{}).join(' · '),latest=packet.timeline.slice(-5).reverse(),todo=openIssues();let q=state.questions.filter(x=>x.status==='sent').length;let unlinked=packet.documents.filter(d=>!(packet.extracted_values||[]).some(x=>x.document_id===d.id)&&d.extraction?.status==='not_extracted').length;return pageHead('A return built from evidence','Current engine result: v3 · '+fmtDate(v3.computed_at)+' · filed return history is preserved; no external tax computation is connected.',`<button class="btn" data-nav="changes">Compare versions</button><button class="btn primary" data-nav="issues">Review next issue →</button>`)+stats()+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>Next decisions</h2><small>${todo.length} open issue records · ordered by severity</small></div><div class="issue-list">${todo.slice(0,4).map(issueCard).join('')||'<div class="empty">No open issue records.</div>'}</div><button class="btn" data-nav="issues">Open all issues</button></section><section class="card"><div class="cardhead"><h2>Federal return snapshot</h2><small>Supplied engine values · no recalculation</small></div><div class="taxrow"><div class="taxbox"><small>Adjusted gross income</small><b>${money(v3.summary.federal.agi)}</b></div><div class="taxbox"><small>Taxable income</small><b>${money(v3.summary.federal.taxable_income)}</b></div><div class="taxbox"><small>Total tax</small><b>${money(v3.summary.federal.total_tax)}</b></div></div><div class="softnote">$${fmtNum(v3.summary.federal.balance_due)} balance due reflects the packet's latest computed version. Filing status and agency events are separate records.</div></section><section class="card"><div class="cardhead"><h2>Review state</h2><small>Calculated from persisted records</small></div><div class="progressline"><span>Issue records resolved</span><b>${issues.length?Math.round((issues.length-openIssues().length)/issues.length*100):0}%</b></div><div class="meter"><span style="width:${issues.length?Math.round((issues.length-openIssues().length)/issues.length*100):0}%"></span></div><div class="mini-list"><div class="mini-row"><i class="minidot ${q?'orange':''}"></i><div>${q} client requests awaiting response<small>Questions persist as evidence records</small></div></div><div class="mini-row"><i class="minidot ${state.review_notes.some(x=>x.status==='open'&&x.blocking)?'red':''}"></i><div>${state.review_notes.filter(x=>x.status==='open'&&x.blocking).length} blocking review notes<small>Sign-off is prevented while a matching blocker remains open</small></div></div><div class="mini-row"><i class="minidot orange"></i><div>${unlinked} structured records without extracted page text<small>Transcript and narrative records are represented as packet summaries</small></div></div></div></section></div><div><section class="card"><div class="cardhead"><h2>Version trail</h2><button class="btn small" data-nav="changes">Compare</button></div><div class="version-row">${packet.return_versions.map((x,i)=>`<button class="version-tile ${i===versionIndex?'active':''}" data-version="${i}"><b>${esc(x.version)}</b><small>${fmtDate(x.computed_at)}</small></button>`).join('')}</div><div class="softnote">v3 is the packet's current return. The displayed v1–v3 comparison uses only supplied engine outputs and their recorded line changes.</div></section><section class="card"><div class="cardhead"><h2>People & assignments</h2><small>At engagement start</small></div><div class="mini-list">${f.staff.filter(s=>s.id==='st-01'||s.id==='st-02'||s.id==='st-03').map(s=>`<div class="mini-row"><i class="minidot"></i><div>${esc(s.name)}<small>${esc(s.role)}${s.credential?', '+esc(s.credential):''}</small></div></div>`).join('')}</div><p class="footnote">Packet assignments: ${esc(assigned||'see firm.assignment_at_start')}.</p></section><section class="card"><div class="cardhead"><h2>Recent activity</h2><button class="btn small" data-nav="settings">Audit log</button></div><div class="mini-list">${latest.map(t=>`<div class="eventline"><i></i><div><b>${esc(t.event.replaceAll('_',' '))}</b><small>${fmtDate(t.at)} · ${esc(t.detail||t.refs?.join(', ')||'Timeline event')}</small></div></div>`).join('')}</div></section><section class="card"><div class="cardhead"><h2>Source packet</h2><small>Imported unchanged</small></div><div class="taxrow"><div class="taxbox"><small>Documents</small><b>${fmtNum(packet.documents?.length)}</b></div><div class="taxbox"><small>Read values</small><b>${fmtNum(packet.extracted_values?.length)}</b></div><div class="taxbox"><small>Return lines</small><b>${fmtNum(totalLines())}</b></div></div></section></div></div>`}
function renderIssues(){let list=issues.filter(i=>issueFilter==='all'||i.severity===issueFilter||issueStatus(i)===issueFilter);return pageHead('Issues & judgments','Automated signals and professional conclusions are recorded separately. A mismatch is a prompt to inspect evidence, not a tax conclusion.',`<button class="btn" data-action="undo">Undo last decision</button><button class="btn primary" data-action="new-question">Ask client</button>`)+stats()+`<section class="card"><div class="cardhead"><h2>Issue register</h2><small>${list.length} records from packet diagnostics and case triage</small></div><div class="filterbar"><input class="search" id="issueSearch" placeholder="Search issue, source or return line…"><select id="issueFilter" class="select"><option value="all">All statuses and severities</option><option value="open">Open</option><option value="in_review">In review</option><option value="resolved">Resolved</option><option value="deferred">Deferred</option><option value="high">High severity</option><option value="medium">Medium severity</option></select><button class="btn" data-action="bulk">Assign selected (${selectedIssues.size})</button></div><div class="issue-list" id="issueList">${list.map(i=>issueCard(i,true)).join('')||'<div class="empty">No matching issues.</div>'}</div><div class="softnote">Starter issue records are curated from packet diagnostics, client messages, return versions, and agency events. Their status is editable and audit logged. Confirmed errors and unresolved judgments are distinguished in the error report.</div><div id="issueDetail"></div></section>`}
function renderReturn(){let ver=current(),lines=ver.lines.filter(l=>{let inScope=returnFilter==='all'||(returnFilter==='federal'&&l.jurisdiction==='federal')||(returnFilter==='california'&&l.jurisdiction==='california')||(returnFilter==='changed'&&(ver.changes_from_previous||[]).some(c=>c.key===l.key));let q=filter.toLowerCase();return inScope&&(!q||`${l.key} ${l.form} ${l.label} ${l.jurisdiction}`.toLowerCase().includes(q))});return pageHead('Return explorer','Browse concepts and schedules, then open a line to see its inputs, supplied rule, source fields, and draft-only review proposals.',`<button class="btn" data-nav="calculations">Calculations</button><button class="btn" data-nav="changes">Version comparison</button>`)+stats()+`<section class="card"><div class="cardhead"><h2>Current return lines · ${esc(ver.version)}</h2><small>${lines.length} shown · ${totalLines()} in packet</small></div><div class="filterbar"><input class="search" id="returnSearch" placeholder="Search tax concept, form, or line…" value="${esc(filter)}"><select id="returnScope" class="select"><option value="all">All jurisdictions</option><option value="federal" ${returnFilter==='federal'?'selected':''}>Federal</option><option value="california" ${returnFilter==='california'?'selected':''}>California</option><option value="changed" ${returnFilter==='changed'?'selected':''}>Changed from prior engine version</option></select></div><div class="tablewrap"><table class="data"><thead><tr><th>Line</th><th>Tax concept</th><th>Jurisdiction</th><th>Supplied amount</th><th>Evidence</th><th>Working proposal</th></tr></thead><tbody>${lines.slice(0,300).map(l=>{let w=state.work_values[l.key];return `<tr data-line="${esc(l.key)}"><td class="mono">${esc(l.key)}</td><td>${esc(l.label)}</td><td>${esc(l.jurisdiction)}</td><td><b>${money(l.value)}</b></td><td>${l.sources?.length?refs(l.sources.slice(0,3)):'<span class="muted">Inputs only</span>'}</td><td>${w?`<span class="pill blue">${money(w.value)} draft</span>`:'—'}</td></tr>`}).join('')}</tbody></table></div>${lines.length>300?'<p class="footnote">Showing first 300 matches. Refine the search to narrow results.</p>':''}<div id="lineDetail">${selectedLine?lineDetail(selectedLine):'<div class="empty">Choose a return line to inspect its calculation and evidence.</div>'}</div></section>`}
function lineDetail(key){let l=current().lines.find(x=>x.key===key);if(!l)return '';let w=state.work_values[key],inputs=(l.inputs||[]).map(k=>current().lines.find(x=>x.key===k)).filter(Boolean);let sources=(l.sources||[]).map(valueById).filter(Boolean);return `<div class="detail"><div class="cardhead"><h3>${esc(l.key)} · ${esc(l.label)}</h3><span class="pill">${esc(l.jurisdiction)} · ${esc(l.form)}</span></div><div class="detail-grid"><div class="field"><label>Supplied engine output · ${esc(current().version)}</label><b>${money(l.value)}</b></div><div class="field"><label>Rule metadata (not recomputed here)</label><b>${esc(l.rule||'Not supplied')}</b></div><div class="field"><label>Line note</label><b>${esc(l.note||'No note in packet')}</b></div><div class="field"><label>Inputs</label><b>${inputs.length?inputs.map(x=>esc(x.key)).join(', '):'No return-line inputs listed'}</b></div></div>${w?`<div class="softnote warningnote"><b>Draft-only proposal:</b> ${money(w.value)} · ${esc(w.reason)} · No supplied engine recomputation is available; official v3 and filed snapshot remain unchanged.</div>`:''}${inputs.length?`<h4 class="sec-title">Calculation inputs</h4><div class="calc-flow">${inputs.map(x=>`<div class="calc-node"><label>${esc(x.key)}</label><b>${money(x.value)}</b><small>${esc(x.label)}</small></div>`).join('<span class="flowarrow">+</span>')}<span class="flowarrow">→</span><div class="calc-node"><label>Supplied output</label><b>${money(l.value)}</b><small>${esc(l.rule||'Engine result')}</small></div></div>`:'<div class="softnote">The packet has no formula for this line. This view shows the supplied rule identifier, declared line inputs, and evidence links without inventing a tax formula.</div>'}${sources.length?`<h4 class="sec-title">Source observations</h4>${sources.map(x=>{const pos=x.position||{};return `<div class="mini-row"><div><b>${esc(x.id)} · ${esc(x.label)}</b><small>${esc(docById(x.document_id)?.title||x.document_id)} · page ${esc(x.page)} · field ${esc(x.field)} · confidence ${Math.round((x.confidence||0)*100)}% · synthetic source box x:${Number(pos.x0||0).toFixed(3)} y:${Number(pos.y0||0).toFixed(3)}</small><div class="sourcepaper">${esc(x.text_as_read||`${x.label}: ${x.value}`)}</div></div><button class="btn small" data-doc="${esc(x.document_id)}">Open source</button></div>`}).join('')}`:''}<h4 class="sec-title">Propose a working value</h4><div class="callout">This creates an auditable, non-filing draft overlay. The supplied computation is not replaced and downstream tax is not recomputed.</div><form class="formgrid" data-form="work-value"><input type="hidden" name="line_key" value="${esc(l.key)}"><div class="formfield"><label>Proposed amount</label><input name="value" type="number" step="0.01" required value="${w?esc(w.value):''}"></div><div class="formfield"><label>Supporting references (comma separated)</label><input name="refs" placeholder="ev-0001, D01"></div><div class="formfield full"><label>Why is a change proposed?</label><textarea name="reason" required>${w?esc(w.reason):''}</textarea></div><div class="formfield full"><button class="btn primary">Save draft proposal</button></div></form></div>`}
function valueById(id){return packet.extracted_values.find(x=>x.id===id)}function docById(id){return packet.documents.find(d=>d.id===id)}
function renderEvidence(){let q=filter.toLowerCase(),docs=packet.documents.filter(d=>(docFilter==='all'||(docFilter==='corrected'&&d.marked_corrected)||(d.extraction?.status===docFilter))&&(!q||`${d.id} ${d.title} ${d.document_type} ${d.issuer} ${d.file_name||''}`.toLowerCase().includes(q)));let d=selectedDoc?docById(selectedDoc):null;return pageHead('Evidence explorer','Packet records stay unchanged. Trace from a return line to the extracted field and simulated printed page, or trace from a document to known downstream return lines.',`<button class="btn" data-action="export">Export evidence index</button>`)+`<section class="card"><div class="cardhead"><h2>Source documents</h2><small>${docs.length} of ${packet.documents.length} · real file contents were not provided</small></div><div class="filterbar"><input class="search" id="docSearch" placeholder="Search ID, issuer, title, filename…" value="${esc(filter)}"><select id="docFilter" class="select"><option value="all">All records</option><option value="partial" ${docFilter==='partial'?'selected':''}>Partial extraction</option><option value="not_extracted" ${docFilter==='not_extracted'?'selected':''}>No structured extraction</option><option value="corrected" ${docFilter==='corrected'?'selected':''}>Corrected documents</option></select></div><div class="tablewrap"><table class="data"><thead><tr><th>Document</th><th>Type / issuer</th><th>Tax year</th><th>Extraction</th><th>Observations</th><th>Trace</th></tr></thead><tbody>${docs.slice(0,200).map(x=>{const vals=packet.extracted_values.filter(e=>e.document_id===x.id).length,lines=linesForDoc(x.id).length;return `<tr data-doc="${esc(x.id)}"><td><b>${esc(x.id)}</b> · ${esc(x.title)}${x.marked_corrected?'<br><span class="pill red">CORRECTED</span>':''}</td><td>${esc(x.document_type)}<small class="muted" style="display:block">${esc(x.issuer)}</small></td><td>${esc(x.tax_year||'—')}</td><td><span class="pill ${x.extraction?.status==='partial'?'red':''}">${esc(x.extraction?.status||'record')}</span></td><td>${vals}</td><td>${lines} return lines</td></tr>`}).join('')}</tbody></table></div>${docs.length>200?'<p class="footnote">Showing first 200; filter to narrow.</p>':''}<div id="docDetail">${d?docDetail(d):'<div class="empty">Select a document to inspect its simulated source page, extracted observations, revision history, and downstream references.</div>'}</div></section><section class="card"><div class="cardhead"><h2>Extracted value lookup</h2><small>3,012 packet observations · paginated</small></div><div class="filterbar"><input class="search" id="valueSearch" placeholder="Search extracted value ID, document, field, or text…" value="${esc(filter)}"><button class="btn" data-page-values="prev">←</button><span class="pill">Page ${valuePage+1}</span><button class="btn" data-page-values="next">→</button></div>${renderValueRows()}</section>`}
function linesForDoc(id){let valueIds=new Set(packet.extracted_values.filter(x=>x.document_id===id).map(x=>x.id));return current().lines.filter(l=>(l.sources||[]).some(r=>valueIds.has(r)))}
function docDetail(d){let pages=d.pages||[],values=packet.extracted_values.filter(x=>x.document_id===d.id),down=linesForDoc(d.id),selectedPage=window.selectedPage||pages[0]?.page;let pg=pages.find(x=>x.page===selectedPage)||pages[0];let revisions=packet.documents.filter(x=>x.document_type===d.document_type&&x.issuer===d.issuer&&x.tax_year===d.tax_year);return `<div class="detail"><div class="cardhead"><h3>${esc(d.id)} · ${esc(d.title)}</h3><span class="pill ${d.marked_corrected?'red':''}">${d.marked_corrected?'CORRECTED':esc(d.extraction?.status||'record')}</span><small>${esc(d.tax_year||'')}</small></div><div class="detail-grid"><div class="field"><label>Issuer / upload source</label><b>${esc(d.issuer)} · ${esc(d.uploaded_by||'not stated')}</b></div><div class="field"><label>Belongs to / received</label><b>${esc(d.belongs_to||'not stated')} · ${fmtDate(d.received_at)}</b></div><div class="field"><label>Source filename</label><b>${esc(d.file_name||'No filename in packet')}</b></div><div class="field"><label>Extraction reason</label><b>${esc(d.extraction?.reason||d.extraction?.status||'not stated')}</b></div></div><p>Linked observations: <b>${values.length}</b> · known v3 downstream lines: <b>${down.length}</b> · revision candidates: ${revisions.map(x=>esc(x.id)).join(', ')||'—'}</p><div class="tabs">${pages.map(p=>`<button class="${p.page===selectedPage?'active':''}" data-doc-page="${p.page}">Page ${p.page}</button>`).join('')||'<span class="footnote">This packet record does not contain printed page text.</span>'}</div><div class="sourcepaper">${esc(pg?.printed_content||'No simulated printed content supplied for this record. The structured record is preserved; original file contents were not included.')}</div>${values.length?`<h4 class="sec-title">Extracted fields</h4><div class="tablewrap"><table class="data"><thead><tr><th>Observation</th><th>Field</th><th>Value</th><th>Read text</th><th>Confidence</th><th>Page</th></tr></thead><tbody>${values.slice(0,150).map(x=>`<tr data-value="${esc(x.id)}"><td class="mono">${esc(x.id)}</td><td>${esc(x.field)} · ${esc(x.label)}</td><td>${esc(x.value)}</td><td>${esc(x.text_as_read||'—')}</td><td>${Math.round((x.confidence||0)*100)}%</td><td>${esc(x.page)}</td></tr>`).join('')}</tbody></table></div>${values.length>150?'<p class="footnote">First 150 values shown for this document; use extracted value search.</p>':''}`:''}${down.length?`<h4 class="sec-title">Reverse trace · used by return lines</h4>${down.slice(0,35).map(l=>`<div class="mini-row"><button class="ref" data-line="${esc(l.key)}">${esc(l.key)}</button><div>${esc(l.label)}<small>${money(l.value)} · ${esc(l.jurisdiction)}</small></div></div>`).join('')}`:'<div class="softnote">No v3 return line links to this record through extracted-value references. Packet does not state whether this is unused, superseded, informational, or unresolved; classification is unknown.</div>'}</div>`}
function renderValueRows(){let q=(filter||'').toLowerCase();let all=packet.extracted_values.filter(x=>!q||`${x.id} ${x.document_id} ${x.field} ${x.label} ${x.value} ${x.text_as_read}`.toLowerCase().includes(q));let pageSize=30,max=Math.max(1,Math.ceil(all.length/pageSize));valuePage=Math.min(valuePage,max-1);return `<div class="tablewrap"><table class="data"><thead><tr><th>Value ID</th><th>Source field</th><th>Value</th><th>Read text</th><th>Confidence</th><th>Source</th></tr></thead><tbody>${all.slice(valuePage*pageSize,(valuePage+1)*pageSize).map(x=>`<tr data-value="${esc(x.id)}"><td class="mono">${esc(x.id)}</td><td>${esc(x.field)} · ${esc(x.label)}</td><td>${esc(x.value)}</td><td>${esc(x.text_as_read||'—')}</td><td>${Math.round((x.confidence||0)*100)}%</td><td><button class="ref" data-doc="${esc(x.document_id)}">${esc(x.document_id)} · p${esc(x.page)}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching values.</td></tr>'}</tbody></table></div><div class="progressline"><span>${all.length.toLocaleString()} matching extracted observations</span><span>${pageSize} per page</span></div>`}
function renderCalculations(){let diagnostics=current().diagnostics||[];let count=0;return pageHead('Calculations & reconciliations','Show the inputs and supplied rule metadata. This packet does not include a runnable tax engine; no unsupported formulas or tax effects are inferred.',`<button class="btn" data-nav="evidence">Browse transactions</button>`)+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>Check: Meridian proceeds summary vs extracted lots</h2><span class="risk high">GAP · $250</span></div><div class="calc-flow"><div class="calc-node"><label>Statement summary · D31</label><b>$71,965</b><small>Printed 1099-B summary</small></div><span class="flowarrow">−</span><div class="calc-node"><label>Detail total · D31 p.10</label><b>$71,715</b><small>Printed and extracted lots</small></div><span class="flowarrow">=</span><div class="calc-node"><label>Difference</label><b>$250</b><small>Unextracted p.32 lot has $250 proceeds / $310 basis</small></div></div><div class="softnote warningnote">Compare the right populations. The $250 proceeds difference matches a missing printed lot; include that lot before concluding the summary is inconsistent. No tax delta is asserted here.</div><div class="refs">${refs(['D31','D31#page10','D31#page32','ev-0703'])}</div></section><section class="card"><div class="cardhead"><h2>Books to tax · Schedule C</h2><small>Packet books records</small></div>${calculationSummary(['SchC','D14','D15','D22','D23','D24','D27'])}<div class="softnote">The packet includes source summaries, extracted records, and supplied tax lines, but not a complete independently executable books-to-tax formula. Review categories and adjustments in supporting records; do not represent this screen as a recalculation.</div></section><section class="card"><div class="cardhead"><h2>High-volume details</h2><small>Search observations by source and field</small></div><div class="taxrow"><button class="taxbox" data-evidence-query="D74"><small>Brightpath transactions</small><b>${fmtNum(packet.extracted_values.filter(x=>x.document_id==='D74').length)} fields</b></button><button class="taxbox" data-evidence-query="D34"><small>Digital assets</small><b>Coinhaven · 1099-DA</b></button><button class="taxbox" data-evidence-query="D23"><small>Business mileage</small><b>Handwritten log</b></button></div><button class="btn" data-nav="evidence">Open searchable detail</button></section></div><div><section class="card"><div class="cardhead"><h2>Engine diagnostics · ${esc(current().version)}</h2><small>${diagnostics.length} supplied flags</small></div><div class="mini-list">${diagnostics.map(d=>`<div class="eventline"><i style="background:${d.severity==='warning'?'#bf7654':'#8da47d'}"></i><div><b>${esc(d.code)}</b><small>${esc(d.message)}</small>${refs((d.refs||[]).slice(0,4))}</div></div>`).join('')}</div></section><section class="card"><div class="cardhead"><h2>Area shortcuts</h2></div>${['D72','D40','D12','D36','D74'].map(id=>{let d=docById(id);return `<div class="mini-row"><i class="minidot"></i><div>${esc(d?.title||id)}<small>${esc(d?.document_type||'')}</small></div><button class="btn small" data-doc="${id}">Inspect</button></div>`}).join('')}</section></div></div>`}
function calculationSummary(keys){let all=current()?.lines||packet.lines||[];let rows=all.filter(l=>keys.some(k=>l.key.includes(k)||l.form.includes(k))).slice(0,14);return `<div class="tablewrap"><table class="data"><thead><tr><th>Line</th><th>Label</th><th>Supplied value</th></tr></thead><tbody>${rows.map(l=>`<tr data-line="${esc(l.key)}"><td class="mono">${esc(l.key)}</td><td>${esc(l.label)}</td><td>${money(l.value)}</td></tr>`).join('')}</tbody></table></div>`}
function renderReview(){const block=state.review_notes.filter(n=>n.blocking&&n.status==='open');return pageHead('Review & sign-off','Reviewer notes bind to a target and exact engine version. A matching open blocker prevents approval; a changed line stales an affected sign-off.',`<button class="btn" data-action="review-note">Add review note</button>`)+stats()+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>Review notes</h2><small>${state.review_notes.length} persisted notes</small></div>${state.review_notes.map(n=>`<div class="issue"><div><h3>${esc(n.target)} ${n.blocking?'<span class="risk high">BLOCKING</span>':'<span class="risk info">NONBLOCKING</span>'}</h3><p>${esc(n.note)}</p><div class="footnote">${esc(n.actor)} · ${fmtDate(n.created_at)} · ${esc(n.version)} · ${esc(n.status)}</div></div>${n.status==='open'?`<button class="btn small" data-close-note="${esc(n.id)}">Resolve note</button>`:''}</div>`).join('')||'<div class="empty">No reviewer notes yet.</div>'}</section><section class="card"><div class="cardhead"><h2>Review scope sign-offs</h2><small>Version-bound</small></div><form class="formgrid" data-form="signoff"><div class="formfield"><label>Scope (e.g. return, F1040.7)</label><input name="scope" required value="return"></div><div class="formfield"><label>Decision</label><select name="decision"><option value="approve">Approve scope</option><option value="request_changes">Request changes</option></select></div><div class="formfield full"><label>Reviewer note</label><input name="note" placeholder="Reviewed v3 evidence and unresolved judgments"></div><div class="formfield full"><button class="btn primary">Record version-bound decision</button></div></form><div class="issue-list">${state.signoffs.map(s=>`<div class="issue"><div><h3>${esc(s.scope)} · ${esc(s.status)} ${s.stale_reason?'<span class="risk high">STALE</span>':''}</h3><p>${esc(s.actor)} · ${esc(s.version)} · ${fmtDate(s.created_at)}${s.stale_reason?' · '+esc(s.stale_reason):''}</p></div></div>`).join('')||'<div class="empty">No sign-offs yet.</div>'}</div><div class="softnote warningnote">Demonstration sign-off only. It does not authorize tax filing or e-file transmission.</div></section></div><div><section class="card"><div class="cardhead"><h2>Readiness gates</h2><small>Live from state</small></div><div class="mini-list"><div class="mini-row"><i class="minidot"></i><div>Current engine version<small>${esc(current().version)} · supplied by packet</small></div></div><div class="mini-row"><i class="minidot ${block.length?'red':''}"></i><div>${block.length} open blocking notes<small>${block.length?'Sign-off blocked for affected scope':'No blockers from reviewer notes'}</small></div></div><div class="mini-row"><i class="minidot orange"></i><div>${openIssues().length} open issues<small>Not automatically converted into tax changes</small></div></div><div class="mini-row"><i class="minidot"></i><div>Filing history recorded<small>Actual acceptance/rejection events in packet</small></div></div></div></section><section class="card"><div class="cardhead"><h2>Start review from an issue</h2></div>${openIssues().slice(0,4).map(i=>`<div class="mini-row"><i class="minidot ${i.severity==='high'?'red':'orange'}"></i><div>${esc(i.title)}<small>${esc(i.id)} · ${esc(issueStatus(i))}</small></div><button class="btn small" data-issue-detail="${esc(i.id)}">Inspect</button></div>`).join('')}</section></div></div>`}
function renderChanges(){let ver=current(),prior=packet.return_versions[Math.max(0,versionIndex-1)],changes=ver.changes_from_previous||[],byKey=new Map(changes.map(x=>[x.key,x]));return pageHead('Changes & versions','Supplied engine versions are immutable baselines. Local work-value proposals are drafts only and never overwrite a computed or filed version.',`<button class="btn" data-action="undo">Undo last supported action</button>`)+`<section class="card"><div class="cardhead"><h2>Choose baseline versions</h2><small>Compare packet outputs</small></div><div class="version-row">${packet.return_versions.map((x,i)=>`<button class="version-tile ${i===versionIndex?'active':''}" data-version="${i}"><b>${esc(x.version)}</b><small>${fmtDate(x.computed_at)} · ${esc(x.trigger||'engine result')}</small></button>`).join('')}</div><div class="taxrow" style="margin-top:11px"><div class="taxbox"><small>${esc(prior.version)} federal AGI</small><b>${money(prior.summary.federal.agi)}</b></div><div class="taxbox"><small>${esc(ver.version)} federal AGI</small><b>${money(ver.summary.federal.agi)}</b></div><div class="taxbox"><small>Line changes listed by packet</small><b>${changes.length}</b></div></div></section><section class="card"><div class="cardhead"><h2>Line-level comparison · ${esc(prior.version)} → ${esc(ver.version)}</h2><small>No inferred differences</small></div><div class="filterbar"><input class="search" id="changeSearch" placeholder="Filter changed line or label…"></div><div class="tablewrap"><table class="data"><thead><tr><th>Return line</th><th>Label</th><th>Prior supplied</th><th>Current supplied</th><th>Delta</th><th>Change kind</th></tr></thead><tbody>${changes.map(c=>{let l=ver.lines.find(x=>x.key===c.key);return `<tr data-change="${esc(c.key)}"><td class="mono">${esc(c.key)}</td><td>${esc(l?.label||'Line record')}</td><td>${money(c.old)}</td><td>${money(c.new)}</td><td>${typeof c.old==='number'&&typeof c.new==='number'?money(c.new-c.old):'—'}</td><td>${esc(c.change)}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No change records for this version.</td></tr>'}</tbody></table></div><div class="softnote">v3 was computed June 23. The packet's later approval, e-file rejection, acceptance, payment, and 2028 notice are timeline events, not additional computed tax versions.</div></section><section class="card"><div class="cardhead"><h2>Proposed values and audit history</h2><small>SQLite persisted</small></div><div class="issue-list">${Object.entries(state.work_values||{}).map(([key,x])=>`<div class="issue"><div><h3>${esc(key)} · ${money(x.value)} <span class="pill blue">DRAFT ONLY</span></h3><p>${esc(x.reason)} · ${esc(x.actor)} · ${fmtDate(x.at)}</p><div class="refs">${refs(x.refs||[])}</div></div><button class="btn small" data-line="${esc(key)}">Inspect</button></div>`).join('')||'<div class="empty">No working value proposals. Source and engine outputs are unchanged.</div>'}</div><div class="mini-list">${state.audit.slice(0,12).map(eventHTML).join('')}</div></section>`}
function eventHTML(e){return `<div class="eventline"><i></i><div><b>${esc(e.action.replaceAll('_',' '))} · ${esc(e.target)}</b><small>${esc(e.actor)} · ${fmtDate(e.created_at)} · ${esc(e.reason)}</small></div></div>`}
function renderRequests(){return pageHead('Client & team questions','Requests and answers are durable evidence records. The selectable Client role is a simulated view, not authenticated client access.',`<button class="btn primary" data-action="new-question">New client request</button>`)+stats()+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>Question timeline</h2><small>${state.questions.length} request records</small></div>${state.questions.map(q=>`<div class="issue"><div><h3>${esc(q.prompt)} <span class="pill ${q.status==='answered'?'green':'blue'}">${esc(q.status)}</span></h3><p>To ${esc(q.recipient)} · ${esc(q.actor)} · ${fmtDate(q.created_at)}</p><div class="refs">${refs(q.refs)}</div>${q.response?`<div class="softnote">Response: ${esc(q.response)}</div>`:''}</div>${q.status==='sent'?`<button class="btn small" data-respond="${esc(q.id)}">Simulate client response</button>`:''}</div>`).join('')||'<div class="empty">No new application-created questions. Packet messages and questionnaire answers remain in evidence search.</div>'}</section></div><div><section class="card"><h2>Useful packet conversations</h2>${packet.client.messages.slice(-7).reverse().map(m=>`<div class="eventline"><i></i><div><b>${esc(m.from)} · ${esc(m.id)}</b><small>${fmtDate(m.sent_at)} · ${esc(m.text)}</small></div></div>`).join('')}</section></div></div>`}
function renderFiling(){let e=packet.tax_agency_records.efile||[],notices=packet.tax_agency_records.notices||[];return pageHead('Filing, amendments & notices','The packet records real rejection and acceptance metadata. This demo manages internal status and evidence only; it does not submit returns or create legal signatures.',`<button class="btn" data-action="client-copy">Record client-copy delivery</button><button class="btn primary" data-action="amendment">Start amendment draft</button>`)+stats()+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>E-file history from packet</h2><small>Submission state is read-only packet evidence</small></div>${e.map(x=>`<div class="issue"><div><h3>${esc(x.jurisdiction)} · <span class="pill ${x.status==='rejected'?'red':'green'}">${esc(x.status)}</span></h3><p>${esc(x.submission_id||'No submission identifier')} · ${fmtDate(x.date)}</p>${(x.errors||[]).map(z=>`<div class="softnote warningnote">${esc(z.code)} · ${esc(z.message)}</div>`).join('')}</div></div>`).join('')}</section><section class="card"><h2>Notice response · Letter 566</h2><p class="sub">Self-contained response workspace: issue scope, evidence, reconciliation, owner, reviewer, response copy and transmission evidence.</p>${notices.filter(n=>n.id==='N-2025-L566').map(n=>`<div class="callout"><b>${esc(n.type)} · response due ${esc(n.response_due)}</b><p>${esc(n.items_under_examination.join(' '))}</p>${refs([n.document,'N-2025-L566'])}</div>`).join('')}<form data-form="exam-note"><div class="formfield" style="margin-top:10px"><label>Internal response checklist / note</label><textarea name="text" placeholder="List evidence to assemble and responsible reviewer…">${esc(state.exam_note||'')}</textarea></div><button class="btn primary" style="margin-top:8px">Save notice note</button></form><div class="softnote">No IRS response has been transmitted by this prototype.</div></section></div><div><section class="card"><div class="cardhead"><h2>Notice register</h2></div>${notices.map(n=>`<div class="detail"><span class="risk ${n.status?.startsWith('Resolved')?'done':'high'}">${n.status?.startsWith('Resolved')?'RESOLVED':'ACTION'}</span><h3 style="margin-top:8px">${esc(n.type)} · ${esc(n.tax_year)}</h3><p>${esc(n.summary||n.items_under_examination?.join('; '))}</p><p>Response due ${esc(n.response_due||'not applicable')} · ${esc(n.status||'Open')}</p>${n.document?refs([n.document]):''}</div>`).join('')}</section><section class="card"><div class="cardhead"><h2>Filed snapshot & client copy</h2></div><div class="mini-row"><i class="minidot"></i><div>Filed return base<small>v3 · frozen packet values</small></div></div><div class="mini-row"><i class="minidot"></i><div>Client copy status<small>${esc(state.client_copy_status)}</small></div></div><div class="mini-row"><i class="minidot orange"></i><div>Amendment records<small>Internal draft task only · no amended calculation or filing service</small></div></div></section></div></div>`}
function renderCarryovers(){let prior=packet.prior_years,carry=prior.carryovers_into_2025,assets=prior.asset_records||[],vassets=current().assets||[];return pageHead('Carryovers & next year','Prior preparer treatment and carryforward values stay linked to their origin. A carried amount is a starting point that still needs review.',`<button class="btn" data-nav="evidence">Find source documents</button>`)+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>2025 carryovers from 2024</h2><small>Origin: filed return D06 and workpaper D07</small></div><div class="tablewrap"><table class="data"><thead><tr><th>Attribute</th><th>Federal</th><th>California</th><th>Origin</th></tr></thead><tbody>${Object.entries(carry).filter(([k])=>k!=='california'&&k!=='sources').map(([k,val])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${money(val)}</td><td>${money(carry.california?.[k])}</td><td>${refs(['D06','D07'])}</td></tr>`).join('')}</tbody></table></div><div class="softnote">California depreciation note: ${esc(carry.california?.note||'See prior-year carryover record')} </div></section><section class="card"><div class="cardhead"><h2>Basis history gaps</h2><small>Prior-year records, including unresolved years</small></div><pre class="sourcepaper">${esc(JSON.stringify(prior.basis_records,null,2))}</pre><div class="refs">${refs(['D06','D07','D40'])}</div></section></div><div><section class="card"><div class="cardhead"><h2>Depreciable asset continuity</h2><small>${assets.length} legacy records · ${vassets.length} v3 current assets</small></div>${assets.map(a=>{let n=vassets.find(x=>x.asset_id===a.asset_id);return `<div class="detail"><h3>${esc(a.description)} <span class="pill">${esc(a.asset_id)}</span></h3><p>${esc(a.activity)} · placed in service ${esc(a.placed_in_service)} · ${esc(a.method)} · ${esc(a.life_years)} years · cost ${money(a.cost)}</p><p>2025 supplied depreciation · federal ${money(n?.federal)} · California ${money(n?.california)} · AMT ${money(n?.amt)}</p><p>Disposal: ${esc(a.disposed?'yes':'no')} · AMT difference ${money(a.amt_difference)}</p><div class="refs">${refs(a.sources||[])}</div></div>`}).join('')}</section><section class="card"><div class="cardhead"><h2>Next-year follow-up</h2></div>${['D36','D40','D72','F6251.11'].map(x=>`<div class="mini-row"><i class="minidot orange"></i><div>${esc(x)}<small>Carry forward with originating evidence; verify before use</small></div><button class="btn small" data-ref="${x}">Open</button></div>`).join('')}</section></div></div>`}
function renderOperations(){let firm=packet.firm,mins=state.time_entries.reduce((a,x)=>a+x.minutes,0);return pageHead('Firm operations','Assignments, work logs, deadlines, and review standards derived from firm packet settings and local work records.',`<button class="btn" data-action="assignment">Assign task</button><button class="btn primary" data-action="time">Log time</button>`)+`<div class="gridstats"><div class="stat"><label>Logged time</label><strong>${(mins/60).toFixed(1)}h</strong><small>${state.time_entries.length} local time entries</small></div><div class="stat"><label>Open work tasks</label><strong>${state.tasks.filter(t=>t.status==='open').length}</strong><small>Application-created assignments</small></div><div class="stat"><label>Engagement overall budget</label><strong>${Object.values(firm.budget_hours||{}).reduce((a,b)=>a+b,0).toFixed(1)}h</strong><small>Budget by area supplied in packet</small></div><div class="stat"><label>Current status</label><strong>Filed</strong><small>2028 examination response open</small></div></div><div class="columns"><div><section class="card"><div class="cardhead"><h2>Staff directory</h2><small>Packet firm roster · not authentication</small></div><div class="tablewrap"><table class="data"><thead><tr><th>Name</th><th>Role</th><th>Credential</th><th>Data clearance</th><th>Active from</th></tr></thead><tbody>${firm.staff.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.role)}</td><td>${esc(s.credential||'—')}</td><td><span class="pill ${s.sensitive_data_clearance?'green':'red'}">${s.sensitive_data_clearance?'Cleared':'Restricted'}</span></td><td>${esc(s.active_from)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="cardhead"><h2>Tasks & assignments</h2><small>Local SQLite</small></div>${state.tasks.map(t=>`<div class="mini-row"><i class="minidot orange"></i><div>${esc(t.title)}<small>${esc(t.assignee)} · due ${esc(t.due_date||'unscheduled')} · ${esc(t.status)}</small></div></div>`).join('')||'<div class="empty">No app-created tasks yet.</div>'}</section></div><div><section class="card"><div class="cardhead"><h2>Area budgets</h2></div>${Object.entries(firm.budget_hours||{}).map(([k,h])=>{let spent=state.time_entries.filter(t=>t.area===k).reduce((a,x)=>a+x.minutes,0)/60;return `<div class="mini-row"><i class="minidot ${spent>h?'red':''}"></i><div style="width:100%">${esc(k.replaceAll('_',' '))}<small>${spent.toFixed(1)}h logged / ${h}h budget</small><div class="meter"><span style="width:${Math.min(spent/h*100,100)}%"></span></div></div></div>`}).join('')}</section><section class="card"><div class="cardhead"><h2>Time entries</h2></div>${state.time_entries.slice(0,12).map(t=>`<div class="eventline"><i></i><div><b>${(t.minutes/60).toFixed(2)}h · ${esc(t.area)}</b><small>${esc(t.actor)} · ${fmtDate(t.created_at)} · ${esc(t.note||'')}</small></div></div>`).join('')||'<div class="empty">No time entries.</div>'}</section></div></div>`}
function renderSettings(){return pageHead('Settings & audit log','Packet validation and application audit history. Role selection is a local demonstration header, not identity management or production access control.',`<button class="btn" data-action="export">Export audit snapshot</button>`)+`<div class="columns"><div><section class="card"><div class="cardhead"><h2>Import validation</h2><small>Original packet SHA-256</small></div><div class="detail-grid">${Object.entries(validation).filter(([k])=>k!=='return_lines_by_version'&&k!=='line_sources_missing_extracted_value').map(([k,x])=>`<div class="field"><label>${esc(k.replaceAll('_',' '))}</label><b>${esc(typeof x==='object'?JSON.stringify(x):x)}</b></div>`).join('')}</div><h4 class="sec-title">Return lines per supplied version</h4><div class="taxrow">${validation.return_lines_by_version.map(x=>`<div class="taxbox"><small>${esc(x.version)}</small><b>${fmtNum(x.lines)} lines</b></div>`).join('')}</div><h4 class="sec-title">Missing value source references</h4>${validation.line_sources_missing_extracted_value.length?`<pre class="sourcepaper">${esc(JSON.stringify(validation.line_sources_missing_extracted_value.slice(0,50),null,2))}</pre>`:'<div class="pill green">No missing extracted-value references in return-line sources</div>'}</section><section class="card"><h2>Access boundaries in demo</h2><div class="mini-list"><div class="mini-row"><i class="minidot"></i><div>Preparer / reviewer / partner / admin<small>Packet tax data visible; only permitted routes may mutate review state.</small></div></div><div class="mini-row"><i class="minidot orange"></i><div>Client projection<small>Summary and application-created client requests only; backend strips identifiers and internal notes.</small></div></div><div class="mini-row"><i class="minidot orange"></i><div>Examiner projection<small>Filed summary, limited examined lines, notices, and e-file events; read-only routes.</small></div></div></div><div class="callout">The X-Demo-Role header can be changed by any local user. These are capability checks for a demo, not authentication. Do not use real taxpayer data or expose the server to a network.</div></section></div><div><section class="card"><div class="cardhead"><h2>Audit events</h2><small>${state.audit.length} recent (up to 150)</small></div><div class="filterbar"><input id="auditSearch" class="search" placeholder="Search action, user, target…"></div><div id="auditList" class="mini-list">${state.audit.map(eventHTML).join('')||'<div class="empty">Actions you take are recorded here.</div>'}</div></section><section class="card"><h2>Firm standards from packet</h2><pre class="sourcepaper">${esc(JSON.stringify(packet.firm.starter_standards,null,2))}</pre></section></div></div>`}
function renderClient(){let qs=state.questions||[],sum=packet.summary;$('#main').innerHTML=pageHead('Your 2025 return','Client demonstration view · limited projection · switching this selector does not sign you in.',`<button class="btn" data-action="new-response">Respond to a request</button>`)+`<div class="gridstats"><div class="stat"><label>Federal total tax</label><strong>${money(sum.federal.total_tax)}</strong><small>Tax year 2025 summary</small></div><div class="stat"><label>Federal balance due</label><strong>${money(sum.federal.balance_due)}</strong><small>Supplied return result</small></div><div class="stat"><label>California refund</label><strong class="green">${money(Math.abs(sum.california.balance_due))}</strong><small>Supplied return result</small></div><div class="stat"><label>Return version</label><strong>${esc(packet.version)}</strong><small>Filing submissions listed below</small></div></div><div class="columns"><section class="card"><h2>Requests from your tax team</h2>${qs.map(q=>`<div class="detail"><span class="pill ${q.status==='answered'?'green':'blue'}">${esc(q.status)}</span><h3 style="margin-top:8px">${esc(q.prompt)}</h3><p>Linked records: ${refs(q.refs||[])}</p>${q.response?`<div class="softnote">Your response: ${esc(q.response)}</div>`:''}<button class="btn small" data-client-response="${esc(q.id)}">${q.status==='answered'?'Add follow-up':'Respond'}</button></div>`).join('')||'<div class="empty">No application-created client requests.</div>'}</section><section class="card"><h2>Filing status</h2>${(packet.filing?.efile||[]).map(x=>`<div class="eventline"><i></i><div><b>${esc(x.jurisdiction)} · ${esc(x.status)}</b><small>${fmtDate(x.date)}</small></div></div>`).join('')}</section></div>`;bind()}
function renderExaminer(){let selected=packet.lines||[];$('#main').innerHTML=pageHead('Filed return & examination','Read-only examiner projection · no internal workpaper comments or taxpayer identity numbers are returned by this API.',`<button class="btn" data-nav="filing">Notice evidence</button>`)+`<div class="gridstats"><div class="stat"><label>Federal AGI</label><strong>${money(packet.summary.federal.agi)}</strong><small>${esc(packet.version)} filed snapshot</small></div><div class="stat"><label>Federal total tax</label><strong>${money(packet.summary.federal.total_tax)}</strong><small>Supplied return result</small></div><div class="stat"><label>California tax</label><strong>${money(packet.summary.california.total_tax)}</strong><small>Supplied return result</small></div><div class="stat"><label>Notice records</label><strong>${packet.notices.length}</strong><small>Packet notice index</small></div></div><section class="card"><div class="cardhead"><h2>Limited lines for examination</h2></div>${calculationSummary(selected.map(x=>x.key))}</section><section class="card"><h2>Notices & filing outcomes</h2>${packet.notices.map(n=>`<div class="detail"><h3>${esc(n.type)} · ${esc(n.tax_year)}</h3><p>${esc(n.summary||n.items_under_examination?.join('; '))}</p><p>Response due ${esc(n.response_due||'—')}</p></div>`).join('')}${packet.efile.map(x=>`<div class="mini-row"><i class="minidot"></i><div>${esc(x.jurisdiction)} · ${esc(x.status)}<small>${fmtDate(x.date)} · ${esc(x.submission_id||'')}</small></div></div>`).join('')}</section>`}
function docPage(id,pageNo){let d=docById(id);if(!d)return null;return {doc:d,page:(d.pages||[]).find(p=>p.page===pageNo)||(d.pages||[])[0]}}
function openRef(ref){if(!packet)return;let r=String(ref),m=r.match(/^(D\d+)(?:#page(\d+))?$/);if(m){selectedDoc=m[1];window.selectedPage=+(m[2]||1);page='evidence';filter='';render();setTimeout(()=>$('#docDetail')?.scrollIntoView({behavior:'smooth',block:'center'}),50);return}let val=valueById(r);if(val){selectedDoc=val.document_id;window.selectedPage=val.page;page='evidence';filter='';render();setTimeout(()=>{const el=$(`[data-value="${CSS.escape(r)}"]`);el?.scrollIntoView({behavior:'smooth',block:'center'});el?.classList.add('highlight')},100);return}let line=current().lines.find(x=>x.key===r)||current().lines.find(x=>x.form+'.'+x.line===r);if(line){selectedLine=line.key;page='return';render();setTimeout(()=>$('#lineDetail')?.scrollIntoView({behavior:'smooth',block:'center'}),60);return}let q=packet.client?.questionnaire?.find(x=>x.id===r),msg=packet.client?.messages?.find(x=>x.id===r);if(q||msg){openModal(`<div class="eyebrow">${q?'CLIENT QUESTIONNAIRE':'CLIENT MESSAGE'} · ${esc(r)}</div><h2>${esc(q?.question||msg?.from)}</h2><div class="sourcepaper">${esc(q?`${q.answer}\nAnswered by: ${q.answered_by} · ${q.answered_at}`:`${msg.text}\n${msg.from} · ${msg.sent_at}`)}</div>`);return}toast('The packet contains no direct detail view for '+r)}
function openSearch(){openModal(`<div class="eyebrow">GLOBAL SEARCH</div><h2>Find in the workpaper</h2><input id="globalSearch" class="search" autofocus placeholder="Search documents, extracted fields, return lines, issues…"><div id="globalResults" class="mini-list" style="margin-top:10px"></div>`);const inp=$('#globalSearch');inp.focus();inp.addEventListener('input',()=>{let q=inp.value.toLowerCase().trim(),hits=[];if(q.length<2){$('#globalResults').innerHTML='';return}for(const d of packet.documents||[]){if(`${d.id} ${d.title} ${d.issuer}`.toLowerCase().includes(q))hits.push({type:'document',label:d.id+' · '+d.title,act:`data-doc="${esc(d.id)}"`})}for(const l of current()?.lines||packet.lines||[]){if(`${l.key} ${l.label}`.toLowerCase().includes(q))hits.push({type:'return line',label:l.key+' · '+l.label,act:`data-line="${esc(l.key)}"`})}for(const i of issues){if(`${i.title} ${i.description}`.toLowerCase().includes(q))hits.push({type:'issue',label:i.title,act:`data-issue-detail="${esc(i.id)}"`})}for(const x of packet.extracted_values||[]){if(hits.length>40)break;if(`${x.id} ${x.field} ${x.label} ${x.text_as_read}`.toLowerCase().includes(q))hits.push({type:'extracted value',label:x.id+' · '+x.label+' · '+x.document_id,act:`data-value="${esc(x.id)}"`})}for(const x of packet.questions||[]){if(`${x.id} ${x.question} ${x.answer||''}`.toLowerCase().includes(q))hits.push({type:'client question',label:x.id+' · '+x.question,act:`data-ref="${esc(x.id)}"`})}$('#globalResults').innerHTML=hits.slice(0,40).map(x=>`<button class="mini-row" ${x.act}><span class="pill">${esc(x.type)}</span><span>${esc(x.label)}</span></button>`).join('')||'<div class="empty">No matches.</div>';bind()})}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('.close').focus()}
function bindOld(){document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.nav)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));document.querySelectorAll('[data-version]').forEach(b=>b.addEventListener('click',()=>{versionIndex=+b.dataset.version;render()}));document.querySelectorAll('[data-line]').forEach(b=>b.addEventListener('click',()=>{selectedLine=b.dataset.line;page='return';render();setTimeout(()=>$('#lineDetail')?.scrollIntoView({behavior:'smooth',block:'center'}),40)}));document.querySelectorAll('[data-doc]').forEach(b=>b.addEventListener('click',()=>{selectedDoc=b.dataset.doc;page='evidence';render();setTimeout(()=>$('#docDetail')?.scrollIntoView({behavior:'smooth',block:'center'}),40)}));document.querySelectorAll('[data-ref]').forEach(b=>b.addEventListener('click',()=>openRef(b.dataset.ref)));document.querySelectorAll('[data-issue-detail]').forEach(b=>b.addEventListener('click',()=>issueDetail(b.dataset.issueDetail)));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('.issue-status').forEach(x=>x.addEventListener('change',()=>setIssue(x.dataset.issue,x.value)));document.querySelectorAll('[data-form]').forEach(f=>f.addEventListener('submit',submitForm));const rs=$('#returnSearch');if(rs)rs.addEventListener('input',()=>{filter=rs.value;selectedLine=null;render()});const sc=$('#returnScope');if(sc)sc.addEventListener('change',()=>{returnFilter=sc.value;render()});const ds=$('#docSearch');if(ds)ds.addEventListener('input',()=>{filter=ds.value;render()});const vs=$('#valueSearch');if(vs)vs.addEventListener('input',()=>{filter=vs.value;valuePage=0;render()});const iss=$('#issueSearch');if(iss)iss.addEventListener('input',()=>{let q=iss.value.toLowerCase();document.querySelectorAll('#issueList .issue').forEach(x=>x.classList.toggle('hide',!x.textContent.toLowerCase().includes(q)))});const ifi=$('#issueFilter');if(ifi)ifi.addEventListener('change',()=>{issueFilter=ifi.value;render()});document.querySelectorAll('[data-doc-page]').forEach(b=>b.addEventListener('click',()=>{window.selectedPage=+b.dataset.docPage;render()}));document.querySelectorAll('[data-value]').forEach(b=>b.addEventListener('click',()=>{let x=valueById(b.dataset.value);if(x){selectedDoc=x.document_id;window.selectedPage=x.page;render();setTimeout(()=>{$(`[data-value="${CSS.escape(x.id)}"]`)?.scrollIntoView({block:'center'})},50)}}));document.querySelectorAll('[data-page-values]').forEach(b=>b.addEventListener('click',()=>{valuePage=Math.max(0,valuePage+(b.dataset.pageValues==='next'?1:-1));render()}));document.querySelectorAll('[data-evidence-query]').forEach(b=>b.addEventListener('click',()=>{page='evidence';filter=b.dataset.evidenceQuery;render()}));const au=$('#auditSearch');if(au)au.addEventListener('input',()=>{let q=au.value.toLowerCase();$('#auditList').innerHTML=state.audit.filter(x=>JSON.stringify(x).toLowerCase().includes(q)).map(eventHTML).join('')});document.querySelectorAll('[data-respond]').forEach(b=>b.addEventListener('click',()=>respond(b.dataset.respond)));document.querySelectorAll('[data-client-response]').forEach(b=>b.addEventListener('click',()=>clientRespond(b.dataset.clientResponse)));}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.nav)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));document.querySelectorAll('[data-version]').forEach(b=>b.addEventListener('click',()=>{versionIndex=+b.dataset.version;render()}));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));document.querySelectorAll('.issue-status').forEach(x=>x.addEventListener('change',()=>setIssue(x.dataset.issue,x.value)));document.querySelectorAll('[data-form]').forEach(f=>f.addEventListener('submit',submitForm));document.querySelectorAll('[data-close-note]').forEach(b=>b.addEventListener('click',async()=>{let reason=prompt('Resolution reason for this review note:');if(reason===null)return;try{await post('/review-note-status',{id:b.dataset.closeNote,status:'resolved',reason});toast('Review note closed and logged');render()}catch(e){toast(e.message)}}));const bindSearch=(id,reset=()=>{})=>{const el=$(id);if(!el)return;el.addEventListener('input',()=>{const val=el.value,start=el.selectionStart;filter=val;reset();render();const n=$(id);if(n){n.focus();n.setSelectionRange(start,start)}})};bindSearch('#returnSearch',()=>selectedLine=null);const sc=$('#returnScope');if(sc)sc.addEventListener('change',()=>{returnFilter=sc.value;render()});bindSearch('#docSearch');const df=$('#docFilter');if(df)df.addEventListener('change',()=>{docFilter=df.value;render()});bindSearch('#valueSearch',()=>valuePage=0);const iss=$('#issueSearch');if(iss)iss.addEventListener('input',()=>{let q=iss.value.toLowerCase();document.querySelectorAll('#issueList .issue').forEach(x=>x.classList.toggle('hide',!x.textContent.toLowerCase().includes(q)))});const ifi=$('#issueFilter');if(ifi)ifi.addEventListener('change',()=>{issueFilter=ifi.value;render()});document.querySelectorAll('[data-doc-page]').forEach(b=>b.addEventListener('click',()=>{window.selectedPage=+b.dataset.docPage;render()}));document.querySelectorAll('[data-evidence-query]').forEach(b=>b.addEventListener('click',()=>{page='evidence';filter=b.dataset.evidenceQuery;render()}));const au=$('#auditSearch');if(au)au.addEventListener('input',()=>{let q=au.value.toLowerCase();$('#auditList').innerHTML=state.audit.filter(x=>JSON.stringify(x).toLowerCase().includes(q)).map(eventHTML).join('')});document.querySelectorAll('[data-respond]').forEach(b=>b.addEventListener('click',()=>respond(b.dataset.respond)));document.querySelectorAll('[data-client-response]').forEach(b=>b.addEventListener('click',()=>clientRespond(b.dataset.clientResponse)));const cs=$('#changeSearch');if(cs)cs.addEventListener('input',()=>{let q=cs.value.toLowerCase();document.querySelectorAll('[data-change]').forEach(x=>x.classList.toggle('hide',!x.textContent.toLowerCase().includes(q)))});}
function go(p){page=p;document.querySelectorAll('.nav [data-page]').forEach(x=>x.classList.toggle('selected',x.dataset.page===p));render();window.scrollTo(0,0)}
async function setIssue(id,status){try{let note=prompt(status==='resolved'?'Resolution explanation and verification evidence:':'Reason for this status change:');if(note===null)return;await post('/decision',{issue_id:id,status,reason:note});toast('Issue decision saved to audit history');render()}catch(e){toast(e.message);await reload()}}
function issueDetail(id){const i=issues.find(x=>x.id===id);if(!i)return;selectedIssue=id;openModal(`<div class="eyebrow">${esc(i.kind)} · ${esc(i.id)}</div><h2>${esc(i.title)}</h2><span class="risk ${esc(i.severity)}">${esc(i.severity.toUpperCase())} · ${esc(issueStatus(i).toUpperCase())}</span><p class="sub" style="margin:12px 0">${esc(i.description)}</p><div class="detail"><h3>Evidence references</h3>${refs(i.refs)}<h3 class="sec-title">Affected return areas</h3><div class="refs">${i.affected.map(x=>`<button class="ref" data-ref="${esc(x)}">${esc(x)}</button>`).join('')}</div></div><form data-form="issue-decision" style="margin-top:13px"><input type="hidden" name="issue_id" value="${esc(id)}"><div class="formgrid"><div class="formfield"><label>Set status</label><select name="status"><option value="open">Open</option><option value="in_review">In review</option><option value="resolved">Resolved</option><option value="deferred">Deferred</option></select></div><div class="formfield"><label>Resolution / status reason</label><input name="reason" required minlength="4" placeholder="Evidence reviewed and rationale…"></div><div class="formfield full"><button class="btn primary">Save decision & audit event</button></div></div></form><div class="softnote">A decision changes the issue record only. It does not silently edit return values or tax calculations.</div>`);bind()}
async function submitForm(e){e.preventDefault();const f=e.currentTarget,fd=new FormData(f),kind=f.dataset.form,d=Object.fromEntries(fd.entries());try{let result;if(kind==='work-value'){d.value=Number(d.value);d.refs=(d.refs||'').split(',').map(x=>x.trim()).filter(Boolean);result=await post('/work-value',d);toast('Draft proposal saved · official return unchanged');page='changes'}else if(kind==='signoff'){d.version=current().version;result=await post('/signoff',d);toast('Review decision recorded');page='review'}else if(kind==='review-note'){d.version=current().version;result=await post('/review-note',d);toast('Review note saved');page='review'}else if(kind==='issue-decision'){result=await post('/decision',d);toast('Decision saved to audit log');$('#modal').close();page='issues'}else if(kind==='question'){d.refs=(d.refs||'').split(',').map(x=>x.trim()).filter(Boolean);await post('/question',d);toast('Client request saved as an evidence record');page='requests'}else if(kind==='client-answer'){d.operation='respond';await post('/question',d);toast('Client response saved');page='requests'}else if(kind==='scenario'){d.base_version=current().version;d.changes=[{alternative_id:d.alternative}];await post('/scenario',d);toast('Hypothetical scenario saved; return unchanged');page='changes'}else if(kind==='task'){d.refs=(d.issue_ids||'[]');try{d.refs=JSON.parse(d.refs)}catch{d.refs=[]}delete d.issue_ids;await post('/task',d);selectedIssues.clear();toast('Task assigned with selected references');page='operations'}else if(kind==='time'){d.minutes=Number(d.minutes);await post('/time',d);toast('Time entry saved');page='operations'}else if(kind==='exam-note'){await post('/exam-note',d);toast('Notice note saved');page='filing'}else return;$('#modal').close();render()}catch(err){toast(err.message)}}
function action(type){if(type==='new-question')openModal(`<div class="eyebrow">CLIENT REQUEST</div><h2>Ask for information</h2><p class="sub">A request is stored in the local audit database and can be answered in the demonstration Client view.</p><form data-form="question"><div class="formgrid"><div class="formfield"><label>Recipient</label><input name="recipient" value="client" required></div><div class="formfield"><label>Evidence references</label><input name="refs" placeholder="qa-14, D31"></div><div class="formfield full"><label>Question</label><textarea name="prompt" required></textarea></div><div class="formfield full"><button class="btn primary">Create request</button></div></div></form>`);
else if(type==='review-note')openModal(`<div class="eyebrow">REVIEW NOTE · ${esc(role)}</div><h2>Add a scoped review note</h2><form data-form="review-note"><div class="formgrid"><div class="formfield"><label>Target line, issue, or return scope</label><input name="target" placeholder="F1040.7 or return" required></div><div class="formfield"><label>Block filing?</label><select name="blocking"><option value="false">No · informational</option><option value="true">Yes · blocking</option></select></div><div class="formfield full"><label>Reviewer note</label><textarea name="note" required></textarea></div><div class="formfield full"><button class="btn primary">Save note</button></div></div></form>`);
else if(type==='new-response')openModal(`<div class="eyebrow">CLIENT RESPONSE</div><h2>Respond to a team request</h2>${state.questions.filter(q=>q.status==='sent'&&q.recipient.toLowerCase()==='client').map(q=>`<div class="detail"><h3>${esc(q.prompt)}</h3><button class="btn small" data-client-response="${esc(q.id)}">Respond</button></div>`).join('')||'<div class="empty">No requests await a response.</div>'}`);
else if(type==='undo'){const e=state.audit.find(x=>!x.reverted_by&&['issue_decision','work_value_proposed'].includes(x.action));if(!e){toast('No supported change to undo');return}openModal(`<div class="eyebrow">UNDO · AUDIT-PRESERVING REVERSAL</div><h2>Reverse the latest supported change?</h2><p class="sub">${esc(e.action)} · ${esc(e.target)} · ${esc(e.reason)}</p><button class="btn danger" id="undoConfirm">Record reversal</button>`);$('#undoConfirm').onclick=async()=>{try{await post('/undo',{event_id:e.id});$('#modal').close();toast('Reversal recorded; original event retained');render()}catch(err){toast(err.message)}}}
else if(type==='bulk'){if(!selectedIssues.size){toast('Select one or more issues first');return}const ids=[...selectedIssues];openModal(`<div class="eyebrow">BULK OPERATIONS · ${ids.length} ISSUES</div><h2>Assign selected issue records</h2><p class="sub">The task retains direct links to each selected issue.</p><form data-form="task"><input type="hidden" name="issue_ids" value='${esc(JSON.stringify(ids))}'><div class="formgrid"><div class="formfield"><label>Assignee</label><select name="assignee">${packet.firm.staff.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="formfield"><label>Due date</label><input type="date" name="due_date"></div><div class="formfield full"><label>Task title</label><input name="title" required value="Review ${ids.length} selected issue${ids.length===1?'':'s'}"></div><div class="formfield full"><button class="btn primary">Create assignment</button></div></div></form>`)}
else if(type==='assignment')openModal(`<div class="eyebrow">ASSIGNMENT</div><h2>Create a work task</h2><form data-form="task"><div class="formgrid"><div class="formfield"><label>Assignee</label><select name="assignee">${packet.firm.staff.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="formfield"><label>Due date</label><input type="date" name="due_date"></div><div class="formfield full"><label>Task</label><input name="title" required></div><div class="formfield full"><button class="btn primary">Assign</button></div></div></form>`);
else if(type==='time')openModal(`<div class="eyebrow">TIME ENTRY</div><h2>Record engagement time</h2><form data-form="time"><div class="formgrid"><div class="formfield"><label>Budget area</label><select name="area">${Object.keys(packet.firm.budget_hours||{}).map(x=>`<option value="${esc(x)}">${esc(x.replaceAll('_',' '))}</option>`).join('')}</select></div><div class="formfield"><label>Minutes</label><input name="minutes" type="number" min="1" max="1440" required></div><div class="formfield full"><label>Note</label><input name="note"></div><div class="formfield full"><button class="btn primary">Save time entry</button></div></div></form>`);
else if(type==='client-copy')confirmAction('Record client copy delivery?','This records a user-confirmed status; it does not send or transmit a tax return copy.',async()=>{await post('/filing-action',{action:'mark_client_copy_sent',reason:'Recorded client-copy delivery by user'});toast('Status recorded');render()});
else if(type==='amendment')confirmAction('Create an amendment preparation task?','The original v3 remains frozen. This creates an internal task only; no amended tax computation or filing is performed.',async()=>{await post('/filing-action',{action:'create_amendment_draft',reason:'Prepare amendment analysis from filed v3'});toast('Amendment preparation task created');render()});
else if(type==='export'){const b=new Blob([JSON.stringify({validation,issues,state,packet_metadata:packet.packet},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='fieldnote-audit-export.json';a.click();URL.revokeObjectURL(a.href)}}
function confirmAction(title,detail,fn){openModal(`<div class="eyebrow">LOCAL STATUS ACTION</div><h2>${esc(title)}</h2><p class="sub">${esc(detail)}</p><button class="btn primary" id="confirmAction">Record action</button>`);$('#confirmAction').onclick=async()=>{try{await fn();$('#modal').close()}catch(e){toast(e.message)}}}
async function respond(id){await clientRespond(id)}function clientRespond(id){openModal(`<div class="eyebrow">SIMULATED CLIENT VIEW</div><h2>Respond to team question</h2><form data-form="client-answer"><input type="hidden" name="operation" value="respond"><input type="hidden" name="id" value="${esc(id)}"><div class="formfield"><label>Your response</label><textarea name="response" required></textarea></div><button class="btn primary" style="margin-top:8px">Save response as evidence</button></form>`);bind()}
function openScenario(){let opts=packet.what_if?.alternatives||[];openModal(`<div class="eyebrow">WHAT-IF · HYPOTHETICAL ONLY</div><h2>Save a scenario from supplied alternatives</h2><p class="sub">No tax values are recalculated. The packet provides fixed alternatives and result summaries; this app keeps a named comparison separate from the return.</p><form data-form="scenario"><div class="formgrid"><div class="formfield full"><label>Scenario label</label><input name="title" required placeholder="Section 179 election comparison"></div><div class="formfield full"><label>Packet alternative</label><select name="alternative">${opts.map(x=>`<option value="${esc(x.id)}">${esc(x.description)}</option>`).join('')}</select></div><div class="formfield full"><button class="btn primary">Save hypothetical record</button></div></div></form>${opts.map(o=>`<div class="detail"><b>${esc(o.description)}</b><p>Federal tax change ${money(o.federal.total_tax_change)} · California tax change ${money(o.california.total_tax_change)}</p></div>`).join('')}`)}
function bindScenarioShortcut(){/* bound below on demand */}
function issueModalStatus(){return null}
document.addEventListener('click',e=>{const hit=s=>e.target.closest(s);if(hit('[data-issue-detail]'))issueDetail(hit('[data-issue-detail]').dataset.issueDetail);if(hit('[data-ref]'))openRef(hit('[data-ref]').dataset.ref);if(hit('[data-scenario]'))openScenario();if(hit('[data-page-values]')){valuePage=Math.max(0,valuePage+(hit('[data-page-values]').dataset.pageValues==='next'?1:-1));render()}if(hit('[data-line]')){selectedLine=hit('[data-line]').dataset.line;page='return';render();setTimeout(()=>$('#lineDetail')?.scrollIntoView({behavior:'smooth',block:'center'}),40)}if(hit('[data-doc]')){selectedDoc=hit('[data-doc]').dataset.doc;page='evidence';render();setTimeout(()=>$('#docDetail')?.scrollIntoView({behavior:'smooth',block:'center'}),40)}if(hit('[data-value]')){const x=valueById(hit('[data-value]').dataset.value);if(x){selectedDoc=x.document_id;window.selectedPage=x.page;page='evidence';filter='';render();setTimeout(()=>{$(`[data-value="${CSS.escape(x.id)}"]`)?.scrollIntoView({block:'center'})},70)}}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-select-issue]'))return;const id=e.target.dataset.selectIssue;if(e.target.checked)selectedIssues.add(id);else selectedIssues.delete(id);const b=$('[data-action="bulk"]');if(b)b.textContent=`Assign selected (${selectedIssues.size})`});
// Add scenario affordance to the changes view after normal rendering.
const renderBase=render;render=function(){renderBase();if(page==='changes'&&role==='Preparer'){const actions=$('.headactions');if(actions&&!actions.querySelector('[data-scenario]')){const b=document.createElement('button');b.className='btn primary';b.textContent='New what-if';b.dataset.scenario='1';actions.append(b)}}};
function onFilterChange(id,val){filter=val;render()}
